#include "renderer.h"

#include <algorithm>
#include <map>
#include <set>
#include <stdexcept>
#include <string>
#include <string_view>
#include <utility>

namespace kernel_codegen::detail {
namespace {

constexpr auto generated_warning = "// clang-format off\n"
                                   "// This file is autogenerated. Do not edit by hand.\n";

struct ExpandedVariant {
    MapOperation const* operation;
    Variant const* variant;
    std::string type;
    std::vector<StorageKind> storage;
};

auto type_set(KernelModule const& module, std::string const& name) -> TypeSet const& {
    auto const found{std::ranges::find_if(module.type_sets, [&](auto const& candidate) {
        return candidate.name == name;
    })};
    if (found == module.type_sets.end()) {
        throw std::invalid_argument{"Unknown kernel type-set: " + name};
    }
    return *found;
}

void expand_storage(MapOperation const& operation,
                    Variant const& variant,
                    std::size_t const operand_index,
                    std::vector<StorageKind>& storage,
                    std::vector<std::vector<StorageKind>>& output) {
    if (operand_index == operation.operands.size()) {
        if (variant.kind == VariantKind::out_of_place &&
            std::ranges::find(storage, StorageKind::array) == storage.end()) {
            return;
        }
        output.push_back(storage);
        return;
    }

    auto const& operand{operation.operands[operand_index]};
    for (auto const kind : operand.storage) {
        if (variant.kind == VariantKind::in_place && operand.name == *variant.target &&
            kind != StorageKind::array) {
            continue;
        }
        storage.push_back(kind);
        expand_storage(operation, variant, operand_index + 1, storage, output);
        storage.pop_back();
    }
}

auto expand(KernelModule const& module) -> std::vector<ExpandedVariant> {
    std::vector<ExpandedVariant> result;
    for (auto const& operation : module.operations) {
        for (auto const& variant : operation.variants) {
            std::vector<std::vector<StorageKind>> combinations;
            std::vector<StorageKind> storage;
            expand_storage(operation, variant, 0, storage, combinations);
            for (auto const& type : type_set(module, operation.type_set).types) {
                for (auto const& combination : combinations) {
                    result.push_back(ExpandedVariant{&operation, &variant, type, combination});
                }
            }
        }
    }
    return result;
}

auto is_target(ExpandedVariant const& expanded, std::size_t const operand_index) -> bool {
    return expanded.variant->kind == VariantKind::in_place &&
           expanded.operation->operands[operand_index].name == *expanded.variant->target;
}

auto public_parameter_type(ExpandedVariant const& expanded,
                           std::size_t const operand_index,
                           bool const owning_target) -> std::string {
    auto const& type{expanded.type};
    if (expanded.storage[operand_index] == StorageKind::scalar) {
        return type + " const";
    }
    if (is_target(expanded, operand_index)) {
        return owning_target ? "TArray<" + type + ">&" : "TArrayView<" + type + "> const";
    }
    return "TConstArrayView<" + type + "> const";
}

auto public_parameters(ExpandedVariant const& expanded, bool const owning_target) -> std::string {
    std::string result;
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (!result.empty()) {
            result += ", ";
        }
        result += public_parameter_type(expanded, index, owning_target) + " " +
                  expanded.operation->operands[index].name;
    }
    if (expanded.variant->kind == VariantKind::out_of_place) {
        if (!result.empty()) {
            result += ", ";
        }
        result += "TArrayView<" + expanded.type + "> const " + expanded.operation->output;
    }
    return result;
}

auto signature_key(ExpandedVariant const& expanded, bool const owning_target) -> std::string {
    auto result{expanded.variant->public_name + "("};
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (index != 0) {
            result += ",";
        }
        result += public_parameter_type(expanded, index, owning_target);
    }
    if (expanded.variant->kind == VariantKind::out_of_place) {
        result += ",TArrayView<" + expanded.type + "> const";
    }
    return result + ")";
}

auto storage_name(StorageKind const storage) -> std::string_view {
    return storage == StorageKind::array ? "array" : "scalar";
}

auto raw_name(ExpandedVariant const& expanded) -> std::string {
    auto result{expanded.operation->name + "_" + expanded.type};
    for (auto const storage : expanded.storage) {
        result += "_";
        result += storage_name(storage);
    }
    result += expanded.variant->kind == VariantKind::in_place ? "_in_place_raw" : "_raw";
    return result;
}

auto pointer_restricted(ExpandedVariant const& expanded, std::size_t const operand_index) -> bool {
    return expanded.operation->aliasing == Aliasing::pairwise_disjoint ||
           is_target(expanded, operand_index);
}

auto raw_parameter_type(ExpandedVariant const& expanded,
                        std::size_t const operand_index) -> std::string {
    auto const& type{expanded.type};
    if (expanded.storage[operand_index] == StorageKind::scalar) {
        return type + " const";
    }
    auto const mutable_pointer{is_target(expanded, operand_index)};
    auto result{type + (mutable_pointer ? "*" : " const*")};
    if (pointer_restricted(expanded, operand_index)) {
        result += " RESTRICT";
    }
    return result;
}

auto raw_parameters(ExpandedVariant const& expanded) -> std::string {
    std::string result;
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (!result.empty()) {
            result += ", ";
        }
        result += raw_parameter_type(expanded, index) + " " +
                  expanded.operation->operands[index].name;
    }
    if (expanded.variant->kind == VariantKind::out_of_place) {
        if (!result.empty()) {
            result += ", ";
        }
        result += expanded.type + "* RESTRICT " + expanded.operation->output;
    }
    result += ", int32 const count";
    return result;
}

auto render_expression(Expression const& expression,
                       MapOperation const& operation,
                       std::vector<StorageKind> const& storage) -> std::string {
    if (expression.kind == ExpressionKind::literal) {
        return expression.value;
    }
    if (expression.kind == ExpressionKind::reference) {
        auto const found{std::ranges::find_if(operation.operands, [&](auto const& operand) {
            return operand.name == expression.value;
        })};
        auto const index{static_cast<std::size_t>(found - operation.operands.begin())};
        return expression.value + (storage[index] == StorageKind::array ? "[i]" : "");
    }
    return "(" + render_expression(expression.arguments[0], operation, storage) + " " +
           expression.value + " " +
           render_expression(expression.arguments[1], operation, storage) + ")";
}

auto array_names(ExpandedVariant const& expanded) -> std::vector<std::string> {
    std::vector<std::string> result;
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (expanded.storage[index] == StorageKind::array) {
            result.push_back(expanded.operation->operands[index].name);
        }
    }
    if (expanded.variant->kind == VariantKind::out_of_place) {
        result.push_back(expanded.operation->output);
    }
    return result;
}

auto count_source(ExpandedVariant const& expanded) -> std::string {
    if (expanded.variant->kind == VariantKind::in_place) {
        return *expanded.variant->target;
    }
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (expanded.storage[index] == StorageKind::array) {
            return expanded.operation->operands[index].name;
        }
    }
    throw std::logic_error{"out-of-place kernel has no array input"};
}

auto raw_arguments(ExpandedVariant const& expanded) -> std::string {
    std::string result;
    for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
        if (!result.empty()) {
            result += ", ";
        }
        auto const& name{expanded.operation->operands[index].name};
        result += expanded.storage[index] == StorageKind::array ? name + ".GetData()" : name;
    }
    if (expanded.variant->kind == VariantKind::out_of_place) {
        result += ", " + expanded.operation->output + ".GetData()";
    }
    result += ", count";
    return result;
}

void append_declaration(std::string& output,
                        KernelModule const& module,
                        ExpandedVariant const& expanded,
                        bool const owning_target) {
    output += "void " + module.export_specifier + " " + expanded.variant->public_name + "(\n";
    auto const parameters{public_parameters(expanded, owning_target)};
    std::size_t start{};
    while (start < parameters.size()) {
        auto const separator{parameters.find(", ", start)};
        output += "    " + parameters.substr(start, separator - start);
        if (separator == std::string::npos) {
            output += ") noexcept;\n\n";
            return;
        }
        output += ",\n";
        start = separator + 2;
    }
}

auto render_header(KernelModule const& module,
                   std::vector<ExpandedVariant> const& variants) -> std::string {
    std::string result{generated_warning};
    result += "#pragma once\n\n";
    result += "#include \"Containers/Array.h\"\n";
    result += "#include \"Containers/ArrayView.h\"\n";
    result += "#include \"CoreTypes.h\"\n\n";
    result += "namespace " + module.cpp_namespace + " {\n\n";

    std::set<std::string> signatures;
    for (auto const& expanded : variants) {
        auto const key{signature_key(expanded, false)};
        if (!signatures.insert(key).second) {
            throw std::invalid_argument{"Duplicate generated kernel signature: " + key};
        }
        append_declaration(result, module, expanded, false);
        if (expanded.variant->kind == VariantKind::in_place) {
            auto const owning_key{signature_key(expanded, true)};
            if (!signatures.insert(owning_key).second) {
                throw std::invalid_argument{"Duplicate generated kernel signature: " + owning_key};
            }
            append_declaration(result, module, expanded, true);
        }
    }
    result += "}\n";
    return result;
}

void append_overlap_check(std::string& output,
                          ExpandedVariant const& expanded,
                          std::string const& lhs,
                          std::string const& rhs) {
    output += "    checkf(!ranges_overlap(" + lhs + ".GetData(), static_cast<std::size_t>(" +
              lhs + ".Num()) * sizeof(" + expanded.type + "), " + rhs +
              ".GetData(), static_cast<std::size_t>(" + rhs + ".Num()) * sizeof(" +
              expanded.type + ")),\n";
    output += "           TEXT(\"" + expanded.variant->public_name + ": " + lhs + " and " + rhs +
              " must not overlap\"));\n";
}

void append_public_definition(std::string& output,
                              ExpandedVariant const& expanded,
                              bool const owning_target) {
    output += "void " + expanded.variant->public_name + "(" +
              public_parameters(expanded, owning_target) + ") noexcept {\n";
    if (owning_target) {
        output += "    " + expanded.variant->public_name + "(";
        for (std::size_t index{}; index < expanded.operation->operands.size(); ++index) {
            if (index != 0) {
                output += ", ";
            }
            auto const& name{expanded.operation->operands[index].name};
            output += is_target(expanded, index) ? "TArrayView<" + expanded.type + ">{" + name + "}"
                                                 : name;
        }
        output += ");\n}\n\n";
        return;
    }

    auto const source{count_source(expanded)};
    output += "    int32 const count{" + source + ".Num()};\n";
    auto const arrays{array_names(expanded)};
    for (auto const& array : arrays) {
        if (array == source) {
            continue;
        }
        output += "    checkf(" + array + ".Num() == count, TEXT(\"" +
                  expanded.variant->public_name + ": " + array + " and " + source +
                  " must have equal lengths\"));\n";
    }

    if (expanded.operation->aliasing == Aliasing::pairwise_disjoint) {
        for (std::size_t lhs{}; lhs < arrays.size(); ++lhs) {
            for (std::size_t rhs{lhs + 1}; rhs < arrays.size(); ++rhs) {
                append_overlap_check(output, expanded, arrays[lhs], arrays[rhs]);
            }
        }
    } else if (expanded.variant->kind == VariantKind::out_of_place) {
        for (auto const& array : arrays) {
            if (array != expanded.operation->output) {
                append_overlap_check(output, expanded, expanded.operation->output, array);
            }
        }
    } else {
        for (auto const& array : arrays) {
            if (array != *expanded.variant->target) {
                append_overlap_check(output, expanded, *expanded.variant->target, array);
            }
        }
    }

    output += "    " + raw_name(expanded) + "(" + raw_arguments(expanded) + ");\n";
    output += "}\n\n";
}

auto render_source(KernelModule const& module,
                   std::vector<ExpandedVariant> const& variants) -> std::string {
    std::string result{generated_warning};
    result += "#include \"" + module.header_include + "\"\n\n";
    result += "#include \"CoreMinimal.h\"\n\n";
    result += "#include <cstddef>\n#include <cstdint>\n\n";
    result += "namespace {\n\n";
    result += "auto ranges_overlap(void const* const lhs, std::size_t const lhs_size,\n";
    result += "                    void const* const rhs, std::size_t const rhs_size) noexcept -> bool {\n";
    result += "    if (lhs_size == 0 || rhs_size == 0) {\n        return false;\n    }\n\n";
    result += "    auto const lhs_address{reinterpret_cast<std::uintptr_t>(lhs)};\n";
    result += "    auto const rhs_address{reinterpret_cast<std::uintptr_t>(rhs)};\n";
    result += "    return lhs_address <= rhs_address ? rhs_address - lhs_address < lhs_size\n";
    result += "                                  : lhs_address - rhs_address < rhs_size;\n}\n\n";

    for (auto const& expanded : variants) {
        result += "void " + raw_name(expanded) + "(" + raw_parameters(expanded) + ") noexcept {\n";
        result += "    for (int32 i{0}; i < count; ++i) {\n";
        auto const destination{expanded.variant->kind == VariantKind::in_place
                                   ? *expanded.variant->target
                                   : expanded.operation->output};
        result += "        " + destination + "[i] = " +
                  render_expression(expanded.operation->expression,
                                    *expanded.operation,
                                    expanded.storage) +
                  ";\n";
        result += "    }\n}\n\n";
    }
    result += "}\n\nnamespace " + module.cpp_namespace + " {\n\n";
    for (auto const& expanded : variants) {
        append_public_definition(result, expanded, false);
        if (expanded.variant->kind == VariantKind::in_place) {
            append_public_definition(result, expanded, true);
        }
    }
    result += "}\n";
    return result;
}

}

auto render(KernelModule const& module) -> std::vector<codegen::GeneratedFile> {
    auto const variants{expand(module)};
    return {
        codegen::GeneratedFile{module.header, render_header(module, variants)},
        codegen::GeneratedFile{module.source, render_source(module, variants)},
    };
}

}
